function nightDetailPage(id){const p=nightDetailPhotos[id];return tideFrame(p.name,`<article class="night-card night-photo-card"><small>${p.date} / 原创故事插画，非实拍</small><button data-night-zoom>整图 / 放大局部</button><figure class="night-detail ${nightPhotoZoom?'is-zoomed':''}"><div class="night-inspection-image"><img src="images/tide/deep/${p.file}.svg" alt="${p.title}，可放大观察物品">${p.parts.map(([k],i)=>{const [x,y,w,h]=nightPhotoRegions[k];return `<button data-night-detail="${k}" aria-label="观察照片区域 ${i+1}" class="night-photo-region ${nightState().details?.includes(k)?'examined':''}" style="left:${x}%;top:${y}%;width:${w}%;height:${h}%"><span>＋</span></button>`;}).join('')}</div></figure><small>点照片上的区域观察，放大后可以拖动查看。</small>${p.parts.filter(([k])=>nightState().details?.includes(k)).map(([,label,text])=>`<section><b>${label}</b><p>${text}</p></section>`).join('')}<small>细节观察保存在这部手机内，不改写原照片。</small></article>${nightReturn(id)}`);}
function nightAsk(key){if(!tide.active||tide.device!=='black'||nightSync()<2||!['label','battery'].includes(key)||!nightState().details?.includes(key))return false;const n=nightState();n.asked=n.asked||[];if(n.asked.includes(key))return false;n.asked.push(key);tideSave();return true;}
function nightPhotoConversation(){const n=nightState(),asked=n.asked||[],lines=[];if(asked.includes('label'))lines.push(['我','桌面照片里，提手上的纸带写的是B-17？','本机新对话'],['阿巡','嗯，借来的那台。实验室借出单上也是B-17。许舟怕还错，在提手上绑了纸带。不是手机的编号。','稍后'],['阿巡','他借机器之前还笑我：一卷空白带也要签字。现在倒是这张纸帮我想起那天。','随后']);if(asked.includes('battery'))lines.push(['我','照片里电池放在旁边，槽里是空的。送修时就这样吗？','本机新对话'],['阿巡','老板让把电池取出来，免得测试时漏液。照片是十六号拍的，买新电池是十七号的事。别拼成同一天。','稍后'],['阿巡','我只记得白天那段。你问门响的事，我真的不知道。','随后']);return `${lines.length?deepBubbles(lines):''}<nav class="night-tabs">${nightSync()>=2&&n.details?.includes('label')&&!asked.includes('label')?'<button data-night-ask="label">问阿巡：照片里的纸带</button>':''}${nightSync()>=2&&n.details?.includes('battery')&&!asked.includes('battery')?'<button data-night-ask="battery">问阿巡：送修时的电池</button>':''}</nav>`;}
const nightBrowserBase=tideBrowser;tideBrowser=function(){return nightBrowserBase()+(tide.device==='black'?`<nav class="night-tabs">${nightLink('period','收藏 / 2008网络剪报')}</nav>`:'');};
const nightSmsBase=tideSms;tideSms=function(){let html=nightSmsBase();if(tide.device!=='black')return html;const stage=nightSync();if(tideView==='smsdeep:mum'&&stage>=1){const n=nightState();if((n.seenStage||0)<1){n.seenStage=1;tideSave();}html=html.replace('<footer>',`<div class="night-card">${deepBubbles([['妈','抽屉那张纸别扔。上次你说修机器要留收条，我替你压在书下面了。','稍后收到'],['妈','你昨天把煎饼拍了半天，今天记得吃热的。','随后']])}</div><footer>`);}const nav=`<nav class="night-tabs">${nightLink('draft','草稿箱 / 未发送')}${stage>=1?nightLink('incoming',(nightState().seenStage||0)<1?'新信息 / 妈':'妈 / 后续信息'):''}${stage>=3?nightLink('after',nightState().choice?'未署名 / 已读':'未署名 / 新信息'):''}</nav>`;return html.replace('</header>','</header>'+nav);};
const nightQQBase=tideQQ;tideQQ=function(){const html=nightQQBase();return tide.device==='black'?html+`<nav class="night-tabs">${nightLink('chat','阿巡 / 漫游记录'+(nightSync()>=2?' · 有新留言':''))}</nav>`:html;};
const nightForumBase=tideForum;tideForum=function(){const html=nightForumBase();return tide.device==='black'?html+`<nav class="night-tabs">${nightLink('forum','末班车有人坐过吗 / 5楼')}</nav>`:html;};
const nightAlbumBase=tideAlbum;tideAlbum=function(){const html=nightAlbumBase();return tide.device==='black'?html+`<nav class="night-photo-grid">${nightLink('photo','DSC0130 / 车票局部')}${Object.entries(nightDetailPhotos).map(([id,p])=>`<button data-night-open="${id}"><img src="images/tide/deep/${p.file}.svg" alt="${p.title}"><span>${p.name}</span></button>`).join('')}</nav>`:html;};
const nightJournalBase=tideJournal;tideJournal=function(){return nightJournalBase()+(tide.device==='black'?`<nav class="night-tabs">${nightLink('receipt','本机便笺 / 报账备忘')}${nightLink('note','未完成的行程纸条')}</nav>`:'');};
const nightPhoneBase=phoneScreen;phoneScreen=function(){if(tide.active&&tide.device==='black'){
 const legacy=/^page:night-(.+)$/.exec(tideView);if(legacy){const id=legacy[1];tideView='night:'+id;phoneState.app=nightApps[id]||'sms';}
 if(tideView.startsWith('night:')){const id=tideView.slice(6);if(nightDetailPhotos[id])return nightDetailPage(id);if(id==='incoming'){if(nightSync()<1)return tideSms();nightState().seenStage=Math.max(nightState().seenStage||0,1);tideSave();return tideFrame('信息 / 妈',`<div class="night-card">${deepBubbles([['妈','抽屉那张纸别扔。上次你说修机器要留收条，我替你压在书下面了。','稍后收到'],['妈','你昨天把煎饼拍了半天，今天记得吃热的。','随后']])}</div>${nightReturn(id)}`);}
 if(id==='chat'){nightRead('chat');if(nightSync()>=2){nightState().qqSeen=true;tideSave();}const rows=[['阿巡','昨晚离线的几句，我这边还能翻出来。','当前'],['许舟（旧记录）','票拍糊了没有？四块钱还得留着报账。','10-17 22:36'],['阿巡（旧记录）','清楚，电池买了没？','10-17 22:37'],['许舟（旧记录）','老板关门了。公交站还亮着。','10-17 22:38']];if(nightSync()>=2)rows.push(['阿巡','刚才找到了另一份缓存。我没看见他上车，也没跟他一起去。别把我的猜测写成证词。','稍后收到'],['阿巡','那张早餐留着。他平常也拍作业、票根，手机里不只有那一晚。','随后']);return tideFrame('QQ / 阿巡',`<div class="night-card">${deepBubbles(rows)}${nightPhotoConversation()}${nightSync()<2?'<small>阿巡：我再找找，实验室网络有点慢。</small>':''}</div>${nightReturn(id)}`);}
 return nightPage(id);
 }
 const result=nightPhoneBase();if(phoneState.app==='home'){const stage=nightSync(),n=nightState();return result+(stage>=1&&(n.seenStage||0)<1?nightLink('incoming','✉ 有新信息'):'')+(stage>=2&&!n.qqSeen?nightLink('chat','QQ 阿巡有新留言'):'')+(stage>=3&&(n.seenStage||0)<3?nightLink('after','✉ 未署名的新信息'):'');}return result;
 }return nightPhoneBase();};
const nightSetViewBase=deepSetView;deepSetView=function(view){if(view.startsWith('page:night-'))return nightOpen(view.slice(11));return nightSetViewBase(view);};
document.addEventListener('submit',e=>{if(!tide.active||tide.device!=='black'||!e.target.matches('[data-night-note]'))return;e.preventDefault();const f=new FormData(e.target);nightState().reply=nightCheck(f.get('time'),f.get('claim'));tideSave();refreshPhone();});
document.addEventListener('click',e=>{if(!tide.active||tide.device!=='black')return;const b=e.target.closest('[data-night-open],[data-night-detail],[data-night-zoom],[data-night-reply],[data-night-ask]');if(!b)return;e.preventDefault();if(b.dataset.nightOpen)return nightOpen(b.dataset.nightOpen);if(b.dataset.nightAsk)nightAsk(b.dataset.nightAsk);if(b.dataset.nightDetail){const key=b.dataset.nightDetail;const p=nightDetailPhotos[tideView.slice(6)];if(!p?.parts.some(([k])=>k===key))return;const n=nightState();n.details=n.details||[];if(!n.details.includes(key))n.details.push(key);tideSave();}if(b.hasAttribute('data-night-zoom'))nightPhotoZoom=!nightPhotoZoom;if(b.dataset.nightReply){nightReply(b.dataset.nightReply);nightState().seenStage=3;tideSave();}refreshPhone();const area=document.querySelector('.night-detail');if(area&&nightPhotoZoom){const points={label:[490,155],battery:[370,220],clock:[470,175],umbrella:[505,325]};const point=points[b.dataset.nightDetail];area.scrollLeft=point?Math.max(0,point[0]-area.clientWidth/2):Math.max(0,(area.scrollWidth-area.clientWidth)/2);area.scrollTop=point?Math.max(0,point[1]-60):Math.max(0,(area.scrollHeight-area.clientHeight)/2);}});
setInterval(()=>{if(!tide.active||tide.device!=='black')return;const before=nightState().stage||0;const after=nightSync();if(after!==before&&!document.activeElement?.matches?.('input,textarea,select')&&['home','sms','qq'].includes(phoneState.app))refreshPhone();},2000);
const nightRefreshBase=refreshPhone;refreshPhone=function(){const result=nightRefreshBase();if(tide.active&&tide.device==='black'&&(phoneState.app==='notes'||tideView==='journal')){const title=document.querySelector('.device-app-title');if(title)title.innerHTML='随手记<span>时光网络</span>';}return result;};
